/**
 * A styled native table, the main data display in ListPage (`design/components/table.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentMember,
  claimSlot,
  classes,
  createCell,
  createDerived,
  elementRef,
  ownerContext,
  pressTableSort,
  provide,
  scope,
  tableSort,
  tableSortColumns,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/table.module.css'
import type { TableCellProps } from './TableCell'
import type { TableHeaderProps } from './TableHeader'
import type { TableRowProps } from './TableRow'

export type CellProps = TableCellProps

export type HeaderProps = TableHeaderProps

export type RowProps = TableRowProps

export type SortDirection = 'asc' | 'desc'

export interface TableProps {
  /**
   * Names the **table** with a real `<caption>`, its first child. `label` names the *scroll
   * region*, which exists only while the columns overflow, so a table that fits has no name.
   * That is fine for a page's main table, but a dashboard's chart twin tables would be announced
   * as "table, table, table". Announced but not drawn unless `captionVisible`, because most
   * tables already have their name on screen: a page title, or the chart they are the twin of.
   */
  caption?: string
  /**
   * Draws the caption above the table as well as announcing it, for a table whose name is not
   * already beside it. Not left to composition as Heading's caption is, because a `Text` above
   * the table would not be connected to it, and `<caption>` is the element for a table's name.
   */
  captionVisible?: boolean
  children?: JSX.Element
  /**
   * The table is a **grid**: one tab stop, arrow keys between cells, and rows that may carry
   * `aria-selected`. Only for a component that owns every cell, in practice DataTable. A
   * hand-composed table is a document of prose and links, browsed with the reader's own keys,
   * and taking the arrow keys for a focus ring would only cost them.
   */
  grid?: boolean
  /**
   * Names the scroll region for keyboard users, usually the page's title.
   */
  label?: string
  /**
   * Rows can be selected in bulk. Only meaningful inside a grid, where it tells a screen reader
   * whether "selected" means one of many or the only one.
   */
  multiselectable?: boolean
  stickyHeader?: boolean
}

/** What Table hands its compound parts. */
export interface TableOwner {
  readonly grid: Exclude<TableProps['grid'], undefined>
}

/** A styled native table, the main data display in ListPage. */
export default function Table(given: TableProps): JSX.Element {
  const props = mergeProps(
    { stickyHeader: false, grid: false, multiselectable: false, captionVisible: false } as Defaults<
      TableProps,
      'stickyHeader' | 'grid' | 'multiselectable' | 'captionVisible'
    >,
    claimSlot(given),
  )
  return scope(() => {
    provide(ownerContext<TableOwner>('Table'), {
      get grid() {
        return props.grid
      },
    })
    const table = elementRef<HTMLElement>()
    const wrapper = elementRef<HTMLElement>()
    const overflowing = createCell(false)
    const at = createCell({ row: 0, column: 0, detail: false })
    const placed = createCell(false)
    const holds = createCell(false)
    const stopIn = createDerived(() => (cell: HTMLTableCellElement): HTMLElement => {
      for (const node of Array.from(
        cell.querySelectorAll<HTMLElement>('button, a[href], input, select, textarea'),
      )) {
        if (node.hasAttribute('disabled') || node.getAttribute('aria-hidden') === 'true') continue
        return node
      }
      return cell
    })
    const gridRows = createDerived(
      () =>
        (element: HTMLTableElement): HTMLTableRowElement[] =>
          Array.from(element.rows).filter((row) => !row.hasAttribute('data-detail')),
    )
    const detailUnder = createDerived(
      () =>
        (row: HTMLTableRowElement | undefined): HTMLTableCellElement | null => {
          const next = row?.nextElementSibling
          return next instanceof HTMLTableRowElement && next.hasAttribute('data-detail')
            ? (next.cells[0] ?? null)
            : null
        },
    )
    const gridCellOf = createDerived(
      () =>
        (element: HTMLTableElement, target: EventTarget | null): HTMLTableCellElement | null => {
          let cell =
            target instanceof HTMLElement ? target.closest<HTMLTableCellElement>('th, td') : null
          while (cell !== null && cell.closest('table') !== element) {
            cell = cell.parentElement?.closest<HTMLTableCellElement>('th, td') ?? null
          }
          if (cell === null || cell.parentElement === null) return null
          return cell.parentElement.hasAttribute('data-detail') && cell !== target ? null : cell
        },
    )
    const positionOf = createDerived(
      () =>
        (
          element: HTMLTableElement,
          cell: HTMLTableCellElement,
          column: number,
        ): { row: number; column: number; detail: boolean } => {
          const row = cell.parentElement as HTMLTableRowElement
          const rows = gridRows.value(element)
          return row.hasAttribute('data-detail')
            ? {
                row: rows.indexOf(row.previousElementSibling as HTMLTableRowElement),
                column,
                detail: true,
              }
            : { row: rows.indexOf(row), column: cell.cellIndex, detail: false }
        },
    )
    const clampCell = createDerived(
      () =>
        (
          element: HTMLTableElement,
          to: { row: number; column: number; detail: boolean },
        ): { row: number; column: number; detail: boolean } | null => {
          const rows = gridRows.value(element)
          const row = Math.min(Math.max(to.row, 0), rows.length - 1)
          const cells = rows[row]?.cells
          if (cells === undefined || cells.length === 0) return null
          return {
            row,
            column: Math.min(Math.max(to.column, 0), cells.length - 1),
            detail: to.detail && row === to.row && detailUnder.value(rows[row]) !== null,
          }
        },
    )
    const startOf = createDerived(
      () =>
        (element: HTMLTableElement): { row: number; column: number; detail: boolean } => {
          const cells = Array.from(gridRows.value(element)[0]?.cells ?? [])
          const column = cells.findIndex((cell) => cell.querySelector('[data-undrawn]') === null)
          return { row: 0, column: Math.max(column, 0), detail: false }
        },
    )
    const whereIn = createDerived(
      () =>
        (element: HTMLTableElement): { row: number; column: number; detail: boolean } =>
          placed.value ? at.value : startOf.value(element),
    )
    const stopAt = createDerived(
      () =>
        (
          element: HTMLTableElement,
          to: { row: number; column: number; detail: boolean },
        ): HTMLElement | null => {
          const row = gridRows.value(element)[to.row]
          if (to.detail) return detailUnder.value(row)
          const cell = row?.cells[to.column]
          return cell === undefined ? null : stopIn.value(cell)
        },
    )
    const rove = createDerived(
      () => (element: HTMLTableElement, to: { row: number; column: number; detail: boolean }) => {
        at.value = to
        for (const [index, row] of gridRows.value(element).entries()) {
          for (const cell of Array.from(row.cells)) {
            const stop = stopIn.value(cell)
            const wanted =
              !to.detail && index === to.row && cell.cellIndex === to.column ? '0' : '-1'
            if (stop !== cell && cell.getAttribute('tabindex') !== '-1')
              cell.setAttribute('tabindex', '-1')
            if (stop.getAttribute('tabindex') !== wanted) stop.setAttribute('tabindex', wanted)
          }
          const under = detailUnder.value(row)
          const held = to.detail && index === to.row ? '0' : '-1'
          if (under !== null && under.getAttribute('tabindex') !== held)
            under.setAttribute('tabindex', held)
        }
      },
    )
    const focusIn = createDerived(() => (event: FocusEvent) => {
      const element = table.value as HTMLTableElement | null
      if (element === null) return
      if (!holds.value) holds.value = true
      const cell = gridCellOf.value(element, event.target)
      if (cell === null) return
      const to = clampCell.value(
        element,
        positionOf.value(element, cell, whereIn.value(element).column),
      )
      if (to === null) return
      placed.value = true
      rove.value(element, to)
    })
    const focusOut = createDerived(() => (event: FocusEvent) => {
      const element = table.value as HTMLTableElement | null
      const left = event.target
      queueMicrotask(() => {
        if (
          element !== null &&
          left instanceof Node &&
          left.isConnected &&
          !element.contains(document.activeElement)
        )
          holds.value = false
      })
    })
    const keyDown = createDerived(() => (event: KeyboardEvent) => {
      const element = table.value as HTMLTableElement | null
      const target = event.target instanceof HTMLElement ? event.target : null
      if (
        element === null ||
        target === null ||
        target.closest(
          'input:not([type="checkbox"]):not([type="radio"]), textarea, [contenteditable]',
        ) !== null
      )
        return
      const cell = gridCellOf.value(element, target)
      if (cell === null) return
      const rows = gridRows.value(element)
      const here = positionOf.value(element, cell, whereIn.value(element).column)
      const forward = getComputedStyle(element).direction === 'rtl' ? -1 : 1
      const far = event.ctrlKey || event.metaKey
      const last = Number.MAX_SAFE_INTEGER
      let next: { row: number; column: number; detail: boolean } | null
      if (here.detail) {
        switch (event.key) {
          case 'ArrowDown':
            next = here.row + 1 < rows.length ? { ...here, row: here.row + 1, detail: false } : null
            break
          case 'ArrowUp':
            next = { ...here, detail: false }
            break
          case 'ArrowRight':
          case 'ArrowLeft':
            next = null
            break
          case 'Home':
            next = far ? { row: 0, column: 0, detail: false } : null
            break
          case 'End':
            next = far ? { row: last, column: last, detail: false } : null
            break
          default:
            return
        }
      } else {
        switch (event.key) {
          case 'ArrowRight':
            next = { ...here, column: here.column + forward }
            break
          case 'ArrowLeft':
            next = { ...here, column: here.column - forward }
            break
          case 'ArrowDown':
            next =
              detailUnder.value(rows[here.row]) !== null
                ? { ...here, detail: true }
                : { ...here, row: here.row + 1 }
            break
          case 'ArrowUp':
            next =
              detailUnder.value(rows[here.row - 1]) !== null
                ? { ...here, row: here.row - 1, detail: true }
                : { ...here, row: here.row - 1 }
            break
          case 'Home':
            next = far ? { row: 0, column: 0, detail: false } : { ...here, column: 0 }
            break
          case 'End':
            next = far ? { row: last, column: last, detail: false } : { ...here, column: last }
            break
          default:
            return
        }
      }
      event.preventDefault()
      const to = next === null ? null : clampCell.value(element, next)
      if (to === null) return
      placed.value = true
      rove.value(element, to)
      stopAt.value(element, to)?.focus()
    })
    const reclamp = createDerived(() => () => {
      const element = table.value as HTMLTableElement | null
      if (element === null || !props.grid) return
      const to = clampCell.value(element, whereIn.value(element))
      if (to === null) return
      rove.value(element, to)
      const fell = document.activeElement === null || document.activeElement === document.body
      if (holds.value && fell) stopAt.value(element, to)?.focus()
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        overflowing.value =
          wrapper.value !== null && wrapper.value.scrollWidth > wrapper.value.clientWidth
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [wrapper.value, wrapper.value?.firstElementChild])
        if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const run = () => {
        reclamp.value()
      }
      const mutation =
        typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
      for (const element of [table.value])
        if (element)
          mutation?.observe(element, {
            childList: true,
            characterData: true,
            subtree: true,
            attributeFilter: ['disabled'],
          })
      release2 = () => {
        mutation?.disconnect()
      }
      run()
    }
    watchEffect(
      createMemo(() => props.grid),
      effect2,
      true,
    )
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran =
        wrapper.value?.parentElement?.closest('[data-member]')?.getAttribute('data-member') ===
        'data-table'
          ? () => {}
          : agentMember({
              member: 'Table',
              element: () => wrapper.value,
              state: () => ({
                'sort-key': tableSort(table.value).key,
                'sort-direction': tableSort(table.value).direction,
                columns: tableSortColumns(table.value),
              }),
              actions: {
                sort: { argument: 'id', run: (value) => pressTableSort(table.value, value) },
              },
            })
      release3 = () => {
        ran()
      }
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    return (
      <div
        class={styles.wrapper}
        data-sticky-header={props.stickyHeader ? '' : undefined}
        data-overflowing={overflowing.value ? '' : undefined}
        tabindex={overflowing.value && !props.grid ? '0' : undefined}
        role={overflowing.value && props.label !== undefined ? 'region' : undefined}
        aria-label={overflowing.value ? props.label : undefined}
        data-member="table"
        ref={wrapper.attach}
      >
        {/* table */}
        <table
          class={styles.table}
          role={props.grid ? 'grid' : undefined}
          aria-multiselectable={props.grid && props.multiselectable ? 'true' : undefined}
          onfocusin={($event: FocusEvent) => props.grid && focusIn.value($event)}
          onfocusout={($event: FocusEvent) => props.grid && focusOut.value($event)}
          onkeydown={($event: KeyboardEvent) => props.grid && keyDown.value($event)}
          ref={table.attach}
        >
          {props.caption !== undefined ? (
            <caption
              class={classes(
                props.captionVisible ? styles.caption : undefined,
                !props.captionVisible ? styles.captionHidden : undefined,
              )}
            >
              {props.caption}
            </caption>
          ) : null}
          {props.children}
        </table>
      </div>
    )
  })
}
